import { useMemo, useRef, useState } from 'react';
import Panel from '../ui/Panel.jsx';
import SearchBox from '../ui/SearchBox.jsx';
import { uuids } from '../tools.js';

// UUID: v4, v7, v1 or v6 UUIDs, regenerated by Generate, a new count or a new version.
export default function UuidTool({ hidden }) {
  const [count, setCount] = useState('1');
  const [version, setVersion] = useState('4');
  const [run, setRun] = useState(0);
  const section = useRef(null);
  const result = useMemo(() => {
    try { return { out: uuids(Number(count), Number(version)), error: '' }; } catch (e) { return { out: '', error: e.message }; }
  }, [count, version, run]);
  return (
    <section data-tab="uuid" hidden={hidden} ref={section}>
      <p className="desc">Generate UUIDs in your browser: random (v4), time-ordered (v7), or time-based (v1, v6) with a random node instead of your network card's address.</p>
      <div className="toolbar">
        <label className="inline">Version
          <select id="uuid-version" value={version} onChange={e => setVersion(e.target.value)}>
            <option value="4">v4 (random)</option>
            <option value="7">v7 (time-ordered)</option>
            <option value="1">v1 (time-based)</option>
            <option value="6">v6 (time-based, sortable)</option>
          </select>
        </label>
        <label className="inline">Count
          <input type="number" id="uuid-count" min="1" max="1000" value={count} onChange={e => setCount(e.target.value)} />
        </label>
        <button id="uuid-gen" type="button" className="primary" onClick={() => setRun(r => r + 1)}>Generate</button>
        <SearchBox sectionRef={section} version={result.out} hidden={hidden} />
      </div>
      <div className="io single">
        <Panel id="uuid-out" label="UUIDs" ext="txt" tab="uuid" className="out" readOnly value={result.out} />
      </div>
      <p className="err" role="alert">{result.error}</p>
    </section>
  );
}
